# Cache for previously computed good numbers
good_cache = {}

def is_good(m):
    if m in good_cache:
        return good_cache[m]

    # Base Case 1: 1-digit numbers
    if m < 10:
        return True

    # Base Case 2: 2-digit numbers (distinct non-zero digits assumed for input m)
    if 10 <= m < 100:
        s = str(m)
        a = int(s[0])
        b = int(s[1])
        # Good if (b divides 10a) OR (a divides b)
        if (10 * a) % b == 0 or b % a == 0:
            good_cache[m] = True
            return True
        else:
            good_cache[m] = False
            return False

    # Recursive step: L >= 3
    digits = [d for d in str(m)]
    L = len(digits)

    for i in range(L):
        d = remove_digit(m, i)

        # Check divisibility
        if m % d == 0:
            # Check if d is a good number (recursive call)
            if is_good(d):
                good_cache[m] = True
                return True

    good_cache[m] = False
    return False

