def is_good(n, memo):
    if n in memo:
        return memo[n]
    s = str(n)
    if len(s) == 1:
        memo[n] = True
        return True

    for i in range(len(s)):
        m_prime_str = s[:i] + s[i+1:]
        if m_prime_str == "":
            continue
        m_prime = int(m_prime_str)
        if n % m_prime == 0:
            if is_good(m_prime, memo):
                memo[n] = True
                return True

    memo[n] = False
    return False

